package com.friendinneed.integration;
import com.fasterxml.jackson.databind.JsonNode; import com.friendinneed.consent.*; import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient;
@Service public class NewsService { private final ConsentService consents; private final RestClient client; private final String key; public NewsService(ConsentService consents,RestClient.Builder builder,@Value("${news.base-url:https://newsapi.org/v2}")String baseUrl,@Value("${news.api-key:}")String key){this.consents=consents;this.client=builder.baseUrl(baseUrl).build();this.key=key;} public List<NewsItem> headlines(UUID profileId,String category,int count){if(!consents.isEnabled(profileId,IntegrationType.NEWS))return List.of();return headlines(category,count);} public List<NewsItem> headlines(String category,int count){if(key.isBlank())return List.of();JsonNode response=client.get().uri(uri->uri.path("/top-headlines").queryParam("category",category).queryParam("pageSize",count).queryParam("apiKey",key).build()).retrieve().body(JsonNode.class);if(response==null)return List.of();List<NewsItem> items=new ArrayList<>();for(JsonNode article:response.path("articles")){items.add(new NewsItem(article.path("title").asText(),article.path("description").asText(),article.path("url").asText(),Instant.parse(article.path("publishedAt").asText())));}return items;} public record NewsItem(String title,String description,String url,Instant publishedAt){} }
